import { CheckoutPaymentIntent, Client, Environment, OrdersController, PaypalExperienceLandingPage, PaypalExperienceUserAction, PaypalWalletContextShippingPreference, ApiError } from "@paypal/paypal-server-sdk";
import { assertSandbox, config } from "@/lib/config";
import { toPayPalValue } from "./money";
import { RealPayPalClient } from "./real";
import { PayPalApiError, type CreatedOrder, type CreateOrderInput } from "./types";

/**
 * Order creation through PayPal's Server SDK, which is generated by APIMatic (it runs on @apimatic/core).
 * The SDK handles OAuth and typed models. It does not retry by default. Calls the SDK doesn't cover, such as Payouts, stay in real.ts.
 * Source: @paypal/paypal-server-sdk 2.5 OrdersController.createOrder (operation orders.create).
 */
export class SdkPayPalClient extends RealPayPalClient {
  private orders: OrdersController;

  constructor(clientId = process.env.PAYPAL_CLIENT_ID ?? "", clientSecret = process.env.PAYPAL_CLIENT_SECRET ?? "") {
    super(clientId, clientSecret);
    assertSandbox();
    this.orders = new OrdersController(
      new Client({
        clientCredentialsAuthCredentials: { oAuthClientId: clientId, oAuthClientSecret: clientSecret },
        environment: Environment.Sandbox,
        timeout: 20_000,
      }),
    );
  }

  override async createOrder(input: CreateOrderInput): Promise<CreatedOrder> {
    try {
      const { result } = await this.orders.createOrder({
        paypalRequestId: input.requestId, // idempotency
        prefer: "return=representation",
        body: {
          intent: input.intent === "AUTHORIZE" ? CheckoutPaymentIntent.Authorize : CheckoutPaymentIntent.Capture,
          purchaseUnits: [
            {
              referenceId: input.referenceId,
              description: input.description,
              amount: { currencyCode: input.amount.currency, value: toPayPalValue(input.amount) },
            },
          ],
          paymentSource: {
            paypal: {
              emailAddress: input.payerEmail,
              experienceContext: {
                brandName: config.appName,
                shippingPreference: PaypalWalletContextShippingPreference.NoShipping,
                userAction: PaypalExperienceUserAction.Continue,
                landingPage: PaypalExperienceLandingPage.Login,
                returnUrl: input.returnUrl,
                cancelUrl: input.cancelUrl,
              },
            },
          },
        },
      });
      const link = result.links?.find((l) => l.rel === "payer-action") ?? result.links?.find((l) => l.rel === "approve");
      if (!result.id || !link) throw new PayPalApiError("Order has no approval link", 500);
      return { id: result.id, status: result.status as CreatedOrder["status"], approveUrl: link.href };
    } catch (err) {
      if (err instanceof ApiError) throw new PayPalApiError(`PayPal createOrder failed (${err.statusCode})`, err.statusCode);
      throw err;
    }
  }
}
